--
-- Triggers `event`
--
DELIMITER $$
CREATE TRIGGER `before_insert_event` BEFORE INSERT ON `event` FOR EACH ROW BEGIN
    SET NEW.employee_id = (SELECT id FROM users WHERE name = NEW.employee_name LIMIT 1);
END
$$
DELIMITER ;

