-- Triggers `leave_status`
--
DELIMITER $$
CREATE TRIGGER `before_insert_leave_status` BEFORE INSERT ON `leave_status` FOR EACH ROW BEGIN
    SET NEW.employee_id = (SELECT id FROM users WHERE name = NEW.employee_name LIMIT 1);
END
$$
DELIMITER ;

